import json, pprint
from collections import Counter, defaultdict

def analyze(path, etapa):
    print(f"\n========== {etapa} {path} ==========")
    events = []
    with open(path) as f:
        for i,line in enumerate(f):
            o=json.loads(line)
            o['_i']=i
            events.append(o)
    types=Counter(o.get('tipo') for o in events)
    print('tipos', dict(types))
    for o in events:
        t=o.get('tipo')
        if t in ('inicio','fin','paso_inicio','paso_fin','paso_omitido','snapshot'):
            slim={k:o[k] for k in o if k not in ('prompt_sistema','prompt_etapa','secuencia','rag_config','_i') and not isinstance(o[k], (dict,list))}
            extra={}
            for k,v in o.items():
                if k in slim: continue
                if isinstance(v,(dict,list)):
                    extra[k]= (list(v.keys()) if isinstance(v,dict) else f'list[{len(v)}]')
            print(f"  [{o['_i']}] {t} {slim} extra={extra}")

analyze('logs/backend.jsonl','backend')
analyze('logs/web.jsonl','web')
analyze('logs/mobile.jsonl','mobile')
