def iter_paso(path, paso_orden):
    with open(path) as f:
        in_paso=False
        for i,line in enumerate(f):
            o=json.loads(line)
            t=o.get('tipo')
            if t=='paso_inicio' and o.get('orden')==paso_orden:
                in_paso=True
                continue
            if t=='paso_fin' and o.get('orden')==paso_orden:
