def item_of(e):
    p=e.get('payload') or {}
    return p.get('item') or {}

def dump_commands_and_files(path, paso):
    print(f'\n################ {path} paso {paso} ################')
    cmds=[]
    files=[]
    msgs=[]
    other_types=defaultdict(int)
    for e in iter_paso(path, paso):
        if e.get('tipo_cli')!='item.completed':
            continue
        it=item_of(e)
        typ=it.get('type')
        if typ=='command_execution':
